contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        require(
            _tos.length == 0
                || (_tos[0] != address(0))
        );

        uint beforeCount = ITransferCounter(caddress).transferFromCount();

        bool ok;
        try c.transfer(from, caddress, _tos, v, _decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        uint afterCount = ITransferCounter(caddress).transferFromCount();

        assert(
            ok
                ? afterCount == beforeCount + _tos.length
                : afterCount == beforeCount
        );
    }

    receive() external payable {}
}

interface ITransferCounter {
    function transferFromCount() external view returns (uint);
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);

        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        try c.transfer(from, caddress, _tos, v, _decimals) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;

        assert(reverted || cBalanceAfter == cBalanceBefore);
    }

    receive() external payable {}
}

